-- Bolá — biblioteca real de logros: 1003 logros distintos (constancia,
-- fuerza por ejercicio, cardio/boxeo/movilidad, medidas corporales, clases
-- reservadas) en vez de los 4 de relleno que había desde la Etapa 2. Cada
-- logro se relaciona con un ejercicio real de la biblioteca (90 en total,
-- ver 20260908000200_exercise_library_real_content.sql) cuando corresponde
-- — el "icon"/"category"/"tier" que agrega esta migración los usa el
-- frontend para pintar una medalla distinta por categoría y nivel (bronce/
-- plata/oro/platino/diamante según tier), no una foto — nunca se inventa
-- una imagen real de algo que no existe (mismo criterio que el resto del
-- catálogo).
--
-- evaluate_achievements() se reescribe completa: antes solo sabía calcular
-- 'workouts' y 'checkins' (y 'streak_days' estaba en el check constraint
-- pero el CASE nunca lo calculaba — se quedaba en 0 para siempre, bug real
-- que se corrige acá de paso). Ahora calcula 12 tipos de métrica de una
-- sola pasada por cliente (jsonb para las que son por-ejercicio) y las
-- 1003 filas del catálogo se evalúan en un solo loop liviano.
--
-- Dispara la reevaluación: terminar un entrenamiento y hacer check-in (ya
-- disparaban antes) + reservar una clase (book_class) + cargar/actualizar
-- una medición corporal (trigger nuevo, porque esa tabla se escribe con
-- INSERT directo, no un RPC).

alter table public.achievements add column if not exists category text;
alter table public.achievements add column if not exists exercise_name text;
alter table public.achievements add column if not exists tier smallint not null default 1;

alter table public.achievements drop constraint if exists achievements_metric_check;
alter table public.achievements add constraint achievements_metric_check check (metric in (
  'workouts', 'checkins', 'streak_days', 'class_bookings', 'personal_records', 'exercise_variety',
  'total_volume_kg', 'exercise_max_weight', 'exercise_sessions',
  'measurement_weight_loss_kg', 'measurement_weight_gain_kg', 'measurement_bodyfat_loss_pct',
  'measurement_waist_loss_cm', 'measurement_arm_gain_cm', 'measurement_chest_gain_cm', 'measurement_thigh_gain_cm'
));

-- Los 4 logros de relleno salen — client_achievements tiene "on delete
-- cascade" (ver 20260905000300_etapa2_features_schema.sql), así que
-- cualquier progreso ya guardado sobre esos 4 se borra con ellos. Es
-- esperable: la app recién lanzó, es la biblioteca real reemplazando a la
-- de relleno, igual que se hizo con exercises y program_templates.
delete from public.achievements;



-- Recalcula el progreso de TODOS los logros de un cliente contra datos
-- reales — una sola pasada: agrega lo que hace falta (jsonb por-ejercicio
-- para las métricas que llevan exercise_name) y después recorre el
-- catálogo completo aplicando la métrica que le toca a cada fila.
create or replace function public.evaluate_achievements(p_client_user_id uuid)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_workouts integer;
  v_checkins integer;
  v_bookings integer;
  v_prs integer;
  v_variety integer;
  v_volume numeric;
  v_streak integer;
  v_max_weight_by_ex jsonb;
  v_sessions_by_ex jsonb;
  v_weight_loss numeric := 0;
  v_weight_gain numeric := 0;
  v_bodyfat_loss numeric := 0;
  v_waist_loss numeric := 0;
  v_arm_gain numeric := 0;
  v_chest_gain numeric := 0;
  v_thigh_gain numeric := 0;
  v_first public.body_measurements%rowtype;
  v_last public.body_measurements%rowtype;
  a record;
  v_val numeric;
  v_progress integer;
begin
  select count(*) into v_workouts from public.workout_sessions where client_user_id = p_client_user_id and finished_at is not null;
  select count(*) into v_checkins from public.checkin_events where client_user_id = p_client_user_id;
  select count(*) into v_bookings from public.class_bookings where client_user_id = p_client_user_id and status = 'reservado';

  -- Racha: el tramo consecutivo de días con check-in más largo que tiene
  -- (no exige que el tramo llegue hasta hoy — si dejó de ir, la racha
  -- lograda queda como logro conseguido en vez de "perderse").
  with days as (
    select distinct (created_at at time zone 'utc')::date as d
    from public.checkin_events where client_user_id = p_client_user_id
  ), grp as (
    select d, d - (row_number() over (order by d))::integer as g from days
  ), streaks as (
    select count(*) as len from grp group by g
  )
  select coalesce(max(len), 0) into v_streak from streaks;

  select count(distinct exercise_name) into v_prs from public.exercise_logs
    where client_user_id = p_client_user_id and weight_kg is not null;
  select count(distinct exercise_name) into v_variety from public.exercise_logs
    where client_user_id = p_client_user_id;
  select coalesce(sum(weight_kg * coalesce(reps, 1)), 0) into v_volume from public.exercise_logs
    where client_user_id = p_client_user_id and weight_kg is not null;

  select coalesce(jsonb_object_agg(exercise_name, max_w), '{}'::jsonb) into v_max_weight_by_ex
    from (select exercise_name, max(weight_kg) as max_w from public.exercise_logs
          where client_user_id = p_client_user_id and weight_kg is not null group by exercise_name) t;

  select coalesce(jsonb_object_agg(exercise_name, sessions), '{}'::jsonb) into v_sessions_by_ex
    from (select exercise_name, count(distinct workout_session_id) as sessions from public.exercise_logs
          where client_user_id = p_client_user_id group by exercise_name) t;

  select * into v_first from public.body_measurements where client_user_id = p_client_user_id order by taken_at asc limit 1;
  select * into v_last from public.body_measurements where client_user_id = p_client_user_id order by taken_at desc limit 1;
  if v_first.id is not null and v_last.id is not null and v_first.id is distinct from v_last.id then
    if v_first.weight_kg is not null and v_last.weight_kg is not null then
      v_weight_loss := greatest(0, v_first.weight_kg - v_last.weight_kg);
      v_weight_gain := greatest(0, v_last.weight_kg - v_first.weight_kg);
    end if;
    if v_first.body_fat_pct is not null and v_last.body_fat_pct is not null then
      v_bodyfat_loss := greatest(0, v_first.body_fat_pct - v_last.body_fat_pct);
    end if;
    if v_first.waist_cm is not null and v_last.waist_cm is not null then
      v_waist_loss := greatest(0, v_first.waist_cm - v_last.waist_cm);
    end if;
    if v_first.arm_cm is not null and v_last.arm_cm is not null then
      v_arm_gain := greatest(0, v_last.arm_cm - v_first.arm_cm);
    end if;
    if v_first.chest_cm is not null and v_last.chest_cm is not null then
      v_chest_gain := greatest(0, v_last.chest_cm - v_first.chest_cm);
    end if;
    if v_first.thigh_cm is not null and v_last.thigh_cm is not null then
      v_thigh_gain := greatest(0, v_last.thigh_cm - v_first.thigh_cm);
    end if;
  end if;

  for a in select * from public.achievements loop
    v_val := case a.metric
      when 'workouts' then v_workouts
      when 'checkins' then v_checkins
      when 'streak_days' then v_streak
      when 'class_bookings' then v_bookings
      when 'personal_records' then v_prs
      when 'exercise_variety' then v_variety
      when 'total_volume_kg' then v_volume
      when 'exercise_max_weight' then coalesce((v_max_weight_by_ex ->> a.exercise_name)::numeric, 0)
      when 'exercise_sessions' then coalesce((v_sessions_by_ex ->> a.exercise_name)::numeric, 0)
      when 'measurement_weight_loss_kg' then v_weight_loss
      when 'measurement_weight_gain_kg' then v_weight_gain
      when 'measurement_bodyfat_loss_pct' then v_bodyfat_loss
      when 'measurement_waist_loss_cm' then v_waist_loss
      when 'measurement_arm_gain_cm' then v_arm_gain
      when 'measurement_chest_gain_cm' then v_chest_gain
      when 'measurement_thigh_gain_cm' then v_thigh_gain
      else 0
    end;
    v_progress := floor(least(v_val, a.target::numeric));

    values (p_client_user_id, a.id, v_progress, case when v_val >= a.target then now() else null end)
    on conflict (client_user_id, achievement_id) do update set
      progress = excluded.progress,
      earned_at = coalesce(public.client_achievements.earned_at, excluded.earned_at);
  end loop;
end;
$$;

-- book_class() gana la reevaluación de logros (antes solo lo hacían
-- finish_workout_session() y check_in_client()) — misma firma, se
-- reemplaza en el lugar, no queda ningún overload viejo.
create or replace function public.book_class(p_session_id uuid)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_gym_id uuid;
  v_capacity smallint;
  v_booked integer;
  v_booking_id uuid;
begin
  if public.app_role() is distinct from 'client' then
    raise exception 'Solo un cliente puede reservar una clase.';
  end if;

  select cs.gym_id, c.capacity into v_gym_id, v_capacity
    from public.class_sessions cs join public.classes c on c.id = cs.class_id
    where cs.id = p_session_id
    for update of cs;

  if v_gym_id is null then
    raise exception 'Esa clase no existe.';
  end if;
  if v_gym_id is distinct from public.app_gym_id() then
    raise exception 'Esa clase es de otro gimnasio.';
  end if;

  select count(*) into v_booked from public.class_bookings
    where session_id = p_session_id and status = 'reservado';

  if v_booked >= v_capacity then
    raise exception 'Esta clase ya no tiene cupo.';
  end if;

  values (p_session_id, auth.uid(), v_gym_id)
  on conflict (session_id, client_user_id) do update set status = 'reservado'
  returning id into v_booking_id;

  perform public.evaluate_achievements(auth.uid());

  return v_booking_id;
end;
$$;

-- Medición corporal: se escribe con INSERT directo (no RPC, ver policies en
-- 20260905000300_etapa2_features_schema.sql), así que la reevaluación de
-- logros va en un trigger, no dentro de una función de escritura.
create or replace function public.trg_evaluate_achievements_on_measurement()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  perform public.evaluate_achievements(new.client_user_id);
  return new;
end;
$$;

drop trigger if exists evaluate_achievements_on_measurement on public.body_measurements;
create trigger evaluate_achievements_on_measurement
  after insert or update on public.body_measurements
  for each row execute function public.trg_evaluate_achievements_on_measurement();
